(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04-t*0.5)*6+Math.cos(y*0.035+t*0.4)*5;
  const w2y = Math.cos(y*0.038+t*0.45)*6+Math.sin(x*0.042-t*0.35)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.7+3)*110, 40+Math.cos(t*0.6+4)*60, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.65+1)*90, 0.065, 2.4, 1.15],
    [200+Math.sin(t*0.55)*60, 220+Math.cos(t*0.75+3)*40, 0.13, 1.6, 0.75],
    [300+Math.cos(t*0.85+5)*100, 30+Math.sin(t*0.4+2)*50, 0.075, 2.2, 1.0]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx-sX*0.7+cx*0.3)**2+(sy-sY*0.7+cy*0.3)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2+=Math.sin(d2*f*1.3-t*sp*0.8+0.5)*w;
    iS2+=Math.cos(d2*f*0.5+t*sp*0.4-1.0)*w;
  }
  const act=(aS+aS2*0.5)/15, inh=(iS+iS2*0.4)/14;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+sy*0.06-t*1.5)*0.1+Math.cos(sx*0.05-sy*0.09+t*1.8)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*5+t*0.9)*0.15;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.15
    +Math.sin((sx*0.2+sy*0.2)+t*2)*0.1;
  const react1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const react2=Math.tanh((act*0.6+inh*0.3-bg*0.2-spiral*0.5)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const vortex=Math.tanh(Math.sin(ang*2+dist*0.03-t)*2)*0.2*Math.max(0,1-dist/200);
  const blend=react1*0.5+react2*0.15+cell*0.2+vortex*0.1+micro*0.05;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,35,85],[12,65,120],[18,110,135],
    [45,160,140],[120,185,120],[195,195,80],
    [220,160,60],[215,110,55],[190,65,60],
    [140,35,55],[75,15,45],[30,8,35],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(react1*Math.PI)*0.25;
  const edge=Math.abs(react1)>0.65?1.2:Math.abs(react2)>0.6?1.1:1.0;
  const depth=1.0+Math.sin(dist*0.02-t*0.5)*0.08;
  const shimmer=Math.max(0,Math.sin(sx*0.5+sy*0.5+t*4)*0.5+0.5)*Math.abs(react1)*0.15;
  const e=edge*depth+shimmer;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*e+shimmer*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*e+shimmer*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*e+shimmer*20)|0)
  ];
}
